namespace sv_95aa8c7a1d7744b49582463984c01e46.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service — one instance per circuit (interactive) or per request (static SSR).
/// All interactive components in the same circuit share this instance.
/// </summary>
public sealed class ThemeService
{
    private ThemeMode _theme = ThemeMode.System;
    private string _accentColor = "#0d6efd";

    public ThemeMode Theme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    /// <summary>
    /// Raised whenever Theme or AccentColor changes.
    /// Interactive components subscribe to this to call StateHasChanged().
    /// </summary>
    public event Action? OnChange;

    private void NotifyChanged() => OnChange?.Invoke();
}

@* Interactive island embedded in the static layout header.
   Because it has @rendermode, it lives in the circuit and can
   subscribe to the scoped ThemeService. *@
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeSvc
@inject IJSRuntime JS

<span class="theme-indicator"
      style="color: @ThemeSvc.AccentColor; cursor: pointer;"
      title="Current theme: @ThemeSvc.Theme"
      @onclick="CycleTheme">
    @ThemeIcon @ThemeSvc.Theme
</span>

@code {
    private string ThemeIcon => ThemeSvc.Theme switch
    {
        ThemeMode.Light  => "☀️",
        ThemeMode.Dark   => "🌙",
        ThemeMode.System => "💻",
        _                => "💻"
    };

    protected override void OnInitialized()
    {
        ThemeSvc.OnChange += HandleThemeChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        // Push theme to the DOM so static content is also styled
        await ApplyThemeToDocument();
    }

    private void CycleTheme()
    {
        ThemeSvc.Theme = ThemeSvc.Theme switch
        {
            ThemeMode.Light  => ThemeMode.Dark,
            ThemeMode.Dark   => ThemeMode.System,
            ThemeMode.System => ThemeMode.Light,
            _                => ThemeMode.Light
        };
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private async Task ApplyThemeToDocument()
    {
        var themeName = ThemeSvc.Theme.ToString().ToLowerInvariant();
        await JS.InvokeVoidAsync("document.documentElement.setAttribute",
            "data-theme", themeName);
        await JS.InvokeVoidAsync("eval",
            $"document.documentElement.style.setProperty('--accent-color', '{ThemeSvc.AccentColor}')");
    }

    public void Dispose()
    {
        ThemeSvc.OnChange -= HandleThemeChanged;
    }
}

