@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeSvc

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card p-4" style="max-width: 480px;">
    <h4>Theme</h4>
    <div class="mb-3">
        <label class="form-label">Mode</label>
        <select class="form-select"
                value="@ThemeSvc.Theme"
                @onchange="OnThemeSelected">
            @foreach (var mode in Enum.GetValues<ThemeMode>())
            {
                <option value="@mode">@mode</option>
            }
        </select>
    </div>

    <div class="mb-3">
        <label class="form-label">Accent Color</label>
        <input type="color" class="form-control form-control-color"
               value="@ThemeSvc.AccentColor"
               @onchange="OnAccentChanged" />
        <small class="text-muted">Current: @ThemeSvc.AccentColor</small>
    </div>

    <p class="mt-3">
        <span style="color: @ThemeSvc.AccentColor; font-weight: bold;">
            Preview: This text uses your accent color.
        </span>
    </p>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeSvc.OnChange += HandleChanged;
    }

    private void OnThemeSelected(ChangeEventArgs e)
    {
        if (Enum.TryParse<ThemeMode>(e.Value?.ToString(), out var mode))
        {
            ThemeSvc.Theme = mode;
        }
    }

    private void OnAccentChanged(ChangeEventArgs e)
    {
        ThemeSvc.AccentColor = e.Value?.ToString() ?? "#0d6efd";
    }

    private void HandleChanged() => InvokeAsync(StateHasChanged);

    public void Dispose()
    {
        ThemeSvc.OnChange -= HandleChanged;
    }
}

